; ==============================================================================
; Data Tables (0xFF8000 - 0xFF828F)
; These appear to be lookup tables (possibly for audio/DSP)
; ==============================================================================

	.org 0xFF8000 - 0xFE0000, 0xFF

DATA_TABLE_8000:
	; TODO: Analyze and document these data tables
	; For now, include as binary
	.incbin "subcpu_boot_data_8000.bin"

; ==============================================================================
; Boot Entry Point (0xFF8290)
; Jumped to from reset handler at 0xFFFEE0
; ==============================================================================

	.org 0xFF8290 - 0xFE0000, 0xFF

BOOT_INIT:
	; Initialize memory controller registers
	stdi8 272, 0
	stdi8 273, 177
	stdi8 266, 4

	; Initialize port function control registers (set all pins to function mode)
	ldio 0x07, 0xFF	; Port 0 all function
	ldio 0x0B, 0xFF	; Port 1 all function
	ldio 0x0F, 0xFF	; Port 2 all function
	ldio 0x1C, 0xFF	; Port 7 data
	ldio 0x1F, 0x07	; Port 7 function
	ldio 0x1E, 0x78	; Port 7 control
	ldio 0x20, 0x3B	; Port 8 data
	ldio 0x23, 0x3F	; Port 8 function
	ldio 0x22, 0xFF	; Port 8 control
	ldio 0x28, 0xFF	; Port A data
	ldio 0x2B, 0x08	; Port A function
	ldio 0x2C, 0xFF	; Port B data
	ldio 0x2F, 0x1F	; Port B function

	; Initialize interrupt control
	ldio 0x30, 0x03
	ldio 0x33, 0x00
	ldio 0x32, 0x02
	ldio 0x34, 0xFF
	ldio 0x37, 0x00
	ldio 0x36, 0x63
	ldio 0x38, 0xFE
	ldio 0x3B, 0x00
	ldio 0x3A, 0x71
	ldio 0x3C, 0xFF
	ldio 0x3F, 0x70
	ldio 0x3E, 0x17

	; Initialize more registers
	ldio 0x44, 0xFF
	ldio 0x47, 0x18
	ldio 0x46, 0x07
	ldio 0x68, 0x00
	ldio 0x6A, 0xFF
	ldio 0x84, 0x1D
	ldio 0x85, 0x1D
	ldio 0x82, 0x00
	ldio 0x88, 0x0A
	ldio 0x89, 0x10
	ldio 0x8A, 0x40
	ldio 0x8B, 0x20
	ldio 0x81, 0x00	; Watchdog control
	set_dd8 1, 0x80	; Watchdog mode
	ldio 0x98, 0x05
	ldio 0x99, 0x00
	ldio 0x9F, 0x00
	ldio 0x9E, 0x00
	set_dd8 7, 0x9E

	; Initialize timer registers
	stdi8 323, 16
	stdi8 327, 17
	stdi8 331, 255
	stdi8 335, 0
	stdi8 339, 18
	stdi8 343, 19
	stdi8 322, 7
	stdi8 326, 3
	stdi8 330, 1

	; Check bit 0 of register 0x40 for clock configuration
	bit_dd8 0, 0x40
	jr nz, BOOT_INIT__clock_alt
	stdi8 334, 31
	jr BOOT_INIT__clock_done
BOOT_INIT__clock_alt:
	stdi8 334, 15
BOOT_INIT__clock_done:
	stdi8 338, 1
	stdi8 342, 1

	; Initialize serial/DMA registers
	ldio 0xD2, 0x01
	ldio 0xD1, 0x00
	and_sd8b_im 0xD3, 0xCF
	and_sd8b_im 0xD3, 0xF0
	ldio 0xD6, 0x29
	lda_dd8l XBC, 0xD6
	ld a, (xbc)
	and a, 0xFC
	set 0, a
	ld (xbc), a
	ldio 0xD5, 0x00
	and_sd8b_im 0xD7, 0xCF
	and_sd8b_im 0xD7, 0xF0

	; Initialize DRAM refresh
	stdi8 357, 113
	stdi8 354, 139
	stdi8 355, 88
	resda 4, 358

	; More timer configuration
	stdi8 320, 102
	stdi8 324, 102
	stdi8 328, 34
	stdi8 332, 34
	stdi8 336, 102
	stdi8 340, 102
	stdi8 321, 129
	stdi8 325, 129
	stdi8 329, 192

	; Check clock config again
	bit_dd8 0, 0x40
	jr nz, BOOT_INIT__clock_alt2
	stdi8 333, 138
	jr BOOT_INIT__clock_done2
BOOT_INIT__clock_alt2:
	stdi8 333, 137
BOOT_INIT__clock_done2:
	stdi8 337, 128
	stdi8 341, 129
	ldio 0xF6, 0x00

	; Set up stack pointer
	lda_24 xwa, 0x0005a2                  ; lda XWA, 0x0005a2 (24-bit encoding)
	ld xsp, xwa

	; Copy interrupt vector trampolines to RAM at 0x0400
	calr COPY_VECTORS	; calr is shorter than call

	; Enable interrupts at level 0
	ei 0

	; Call initialization routines
	call INIT_MEMORY_TEST	; 0xFF8956 - Memory test
	call INIT_DMA_SERIAL	; 0xFF85AE - DMA/Serial init
	call INIT_TONE_GEN	; 0xFF84A8 - Tone generator init

	jr __jrt_nop_FF840C	; Jump to main loop (2-byte NOP in fall-through)
__jrt_nop_FF840C:

; ==============================================================================
; Main Loop - Wait for payload ready, then call it
; ==============================================================================

MAIN_LOOP:
	resda 6, 1278	; Clear ready flag
MAIN_LOOP__wait_loop:
	bitda 6, 1278	; Check if payload ready
	jr z, MAIN_LOOP__check_status
	ei 6	; Enable interrupt level 6
	call PAYLOAD_ENTRY	; Call payload at 0x0400 (4-byte encoding)
MAIN_LOOP__check_status:
	; Read serial status and update control
	ldcf_dd8 1, 0x30
	scc8 c, a
	cpl a
	and a, 0x1
	sla a, 1
	and_sd8b_im 0x30, 0xFD
	or_sd8b_mr A, 0x30
	jr MAIN_LOOP__wait_loop

; ==============================================================================
; DEFAULT_HANDLER (0xFF8432) - Default interrupt handler (just returns)
; ==============================================================================

	.org 0xFF8432 - 0xFE0000, 0xFF

DEFAULT_HANDLER:
	reti

; ==============================================================================
; RESET_ENTRY (0xFF8433) - Alternative reset/NMI handler
; ==============================================================================

RESET_ENTRY:
	jrl BOOT_INIT	; Jump back to boot init (3-byte relative jump)
	reti	; 0xFF8436: Alternate entry point

; ==============================================================================
; TONE_GEN_CHANNEL_INIT (0xFF8437) - Initialize tone generator channels
; Loops through 4 channels and calls TONE_GEN_WRITE for each
; ==============================================================================

TONE_GEN_CHANNEL_INIT:
	push_werp 0xFA	; Save QIZ (QIZH used as loop counter)
	cpdi16_24 16776942, 65535	; cp (0xFFFEEE), 0xFFFF - check init flag
	jr nz, TONE_GEN_CHANNEL_INIT__done	; Skip if memory not 0xFFFF (already initialized)
	ldi_berp 0xFB, 0	; Clear loop counter (QIZH = 0)
TONE_GEN_CHANNEL_INIT__loop:
	ldto_berp A, 0xFB	; A = loop counter (QIZH)
	extz wa	; Zero-extend A to WA
	ldto_berp C, 0xFB	; C = loop counter (QIZH)
	extz bc	; Zero-extend C to BC
	sla bc, 2	; BC <<= 2 (multiply by 4 for table index)
	lda_24 xde, 0xfffef0                  ; XDE = pointer to channel config table
	ld_sril3 XBC, 0x07, 0xE8, 0xE4	; XBC = config[channel] (4 bytes per entry)
	call TONE_GEN_WRITE	; Write config to tone generator
	inc1_berp 0xFB	; Increment loop counter
	cpi_berp 0xFB, 4	; Compare counter with 4
	jr c, TONE_GEN_CHANNEL_INIT__loop	; Loop while counter < 4
TONE_GEN_CHANNEL_INIT__done:
	pop_werp 0xFA	; Restore QIZ
	ret

; ==============================================================================
; COPY_VECTORS (0xFF846D) - Copy interrupt trampolines to RAM
; ==============================================================================

COPY_VECTORS:
	ld xde, 0x400	; Destination: RAM at 0x0400
	ld xhl, 0xFF8F6C	; Source: Trampoline data in ROM
	ld xbc, 0xE1	; Count: 225 bytes (45 handlers x 5 bytes)
	or xbc, xbc
	jr z, COPY_VECTORS__done
	mrib2 0x83, 0x11	; Block copy (TMP94C241 encoding)
	cpi_werp 0xE6, 0
	jr z, COPY_VECTORS__done
	ldto_werp WA, 0xE6
COPY_VECTORS__copy_rest:
	mrib2 0x83, 0x11	; TMP94C241 encoding
	djnz xwa, COPY_VECTORS__copy_rest
COPY_VECTORS__done:
	ret

; ==============================================================================
; HALT_LOOP (0xFF8490) - Halt and loop forever (error condition)
; ==============================================================================

	.org 0xFF8490 - 0xFE0000, 0xFF

HALT_LOOP:
	res_dd8 0, 0x38	; Disable serial
HALT_LOOP__halt:
	halt	; Halt CPU
	jr HALT_LOOP__halt	; Loop forever if we wake (jump to halt, not start)

; ==============================================================================
; Stub routines (0xFF8496) - Return 0 in HL
; These are placeholder/unused routines
; ==============================================================================

OUTPUT_NOP_RET:
	lds hl, 0
	ret

STUB_8499:
	lds hl, 0
	ret

STUB_849C:
	lds hl, 0
	ret

STUB_849F:
	lds hl, 0
	ret

STUB_84A2:
	lds hl, 0
	ret

STUB_84A5:
	lds hl, 0
	ret

; ==============================================================================
; INIT_TONE_GEN (0xFF84A8) - Initialize tone generator at 0x130000
; ==============================================================================

INIT_TONE_GEN:
	link32 0xEE, 0x0C, 0xF8, 0xFF	; Reserve 8 bytes on stack
	xor xwa, xwa
	ld xwa, 0x5A5A5A5A	; Test pattern
	ld (xiz - 8), xwa
	ld (xiz - 4), xwa
	lda xwa, (xiz - 8)
	push xwa
	lds bc, 0
	calr TONE_GEN_WRITE	; Call relative (3-byte encoding)
	pop xwa
	push xwa
	lds bc, 1
	calr TONE_GEN_WRITE
	pop xwa
	push xwa
	lds bc, 2
	calr TONE_GEN_WRITE
	pop xwa
	push xwa
	lds bc, 3
	calr TONE_GEN_WRITE
	pop xwa

	; Initialize tone generator registers
	ld xbc, 0x130000
	ld xwa, 0x101001F
	ldb d, 0x4	; TMP94C241 encoding (24 04)
INIT_TONE_GEN__init_loop:
	ld w, a
	ld (xbc), xwa
	add a, 0x20
	djnz8 d, INIT_TONE_GEN__init_loop
	unlk32 xiz
	ret

; ==============================================================================
; TONE_GEN_WRITE (0xFF84F1) - Write to tone generator
; ==============================================================================

	.org 0xFF84F1 - 0xFE0000, 0xFF

TONE_GEN_WRITE:
	pushw de
	sll a, 5	; A = A << 5
	set 4, a	; A |= 0x10
	ld xhl, 0x130000
	ldb d, 0x8
TONE_GEN_WRITE__write_loop:
	ld (xhl), a
	ld_spib E, 0xE4
	ld (xhl + 2), e
	inc 1, a
	djnz8 d, TONE_GEN_WRITE__write_loop
	popw de
	ret

; ==============================================================================
; WRITE_TONE_REG_MULTI_CHANNEL (0xFF850E) - Push registers and call WRITE_TONE_REG_SINGLE_CHANNEL multiple times
; Appears to write multiple register pairs to tone generator
; ==============================================================================

WRITE_TONE_REG_MULTI_CHANNEL:
	push xbc
	push xde
	pushw 0x1	; Push channel 1
	calr WRITE_TONE_REG_SINGLE_CHANNEL
	mrdl3 0xAF, 0x0A, 0x21	; ld XBC, (XSP+0x0A)
	ld xde, xiz	; ld XDE, XIZ
	pushw 0x0	; Push channel 0
	calr WRITE_TONE_REG_SINGLE_CHANNEL
	ld xbc, xwa
	ld xde, xhl
	pushw 0x2	; Push channel 2
	calr WRITE_TONE_REG_SINGLE_CHANNEL
	ld xbc, xix
	ld xde, xiy
	pushw 0x3	; Push channel 3
	calr WRITE_TONE_REG_SINGLE_CHANNEL
	inc 8, xsp	; inc 0, XSP (adjust stack)
	pop xde
	pop xbc
	ret

; ==============================================================================
; WRITE_TONE_REG_SINGLE_CHANNEL (0xFF853A) - Write register pair to tone generator channel
; ==============================================================================

WRITE_TONE_REG_SINGLE_CHANNEL:
	push xiy
	pushw wa
	pushw bc
	mrdb3 0x8F, 0x0C, 0x21	; ld A, (XSP+0x0C) - get channel from stack
	sll a, 5	; A = A << 5
	set 4, a	; A |= 0x10
	ld xiy, 0x130000
	ld (xiy), a	; Write register address
	ld (xiy + 2), c	; Write C
	inc 1, a
	ld (xiy), a
	ld (xiy + 2), b	; Write B
	inc 1, a
	ld (xiy), a
	ldto_werp BC, 0xE6	; ld BC, QBC (high word of XBC)
	ld (xiy + 2), c
	inc 1, a
	ld (xiy), a
	ld (xiy + 2), b
	inc 1, a
	ld (xiy), a
	ld (xiy + 2), e	; Write E
	inc 1, a
	ld (xiy), a
	ld (xiy + 2), d	; Write D
	inc 1, a
	ld (xiy), a
	ldto_werp BC, 0xEA	; ld BC, QDE (high word of XDE)
	ld (xiy + 2), c
	inc 1, a
	ld (xiy), a
	ld (xiy + 2), b
	popw bc
	popw wa
	pop xiy
	ret

; ==============================================================================
; COPY_WORDS (0xFF858B) - Copy words from XBC to XDE, count in DE
; ==============================================================================

COPY_WORDS:
	ld xix, xwa
	ld xiy, xbc
	ld bc, de
	ldirw	; ldirw (word block copy)
	ret

; ==============================================================================
; FILL_WORDS (0xFF8594) - Fill memory at XWA with BC, count in DE
; ==============================================================================

FILL_WORDS:
	st_dpiw BC, 0xE1	; ld (XWA+), BC
	djnz16 de, -6	; djnz DE, FILL_WORDS
	ret

; ==============================================================================
; CHECKSUM_CALC (0xFF859B) - Calculate checksum from XWA to XWA+XBC
; Returns complemented sum in HL
; ==============================================================================

CHECKSUM_CALC:
	xor xhl, xhl	; Clear XHL
	extz xbc	; Zero-extend BC to XBC
	add xbc, xwa	; End address = start + count
CHECKSUM_CALC__loop:
	add_spil XHL, 0xE2	; add XHL, (XWA+)
	cp xwa, xbc
	jr lt, CHECKSUM_CALC__loop	; Loop while XWA < end
	cpl hl	; Complement result
	ret

; ==============================================================================
; STUB_85AB (0xFF85AB) - Return 0 in HL
; ==============================================================================

STUB_85AB:
	lds hl, 0
	ret

; ==============================================================================
; INIT_DMA_SERIAL (0xFF85AE) - Initialize DMA for payload reception
; ==============================================================================
;
; Configures DMA channels and serial hardware for inter-CPU communication.
; Called once during boot before the main loop begins waiting for payload.
;
; DMA Channel Configuration:
;   Channel 0: Receive from latch (source = 0x120000, fixed)
;   Channel 2: Send to latch (dest = 0x120000, used for responses)
;
; After this initialization:
;   - DMA_XFER_STATE = 0 (idle)
;   - CMD_PROCESSING_STATE = 0 (idle)
;   - Sub CPU is ready to receive payload from main CPU
; ==============================================================================

INIT_DMA_SERIAL:
	and_sd8b_im 0xE5, 0xF8	; Clear E5 bits
	res_dd8 2, 0x80	; Watchdog mode
	lda_dd8l XBC, 0xEC
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	lda_dd8l XBC, 0xED
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	lda_dd8l XBC, 0xF0
	ld a, (xbc)
	and a, 0xF8
	set 0, a
	ld (xbc), a
	ldio 0x8A, 0x0A

	; Set up DMA for inter-CPU latch at 0x120000
	lda_24 xwa, 0x120000
	ldc_cr32 xwa, 0x28	; DMA channel 2 destination = 0x120000
	ldb a, 0x8
	ldc_cr8 a, 0x4A	; DMA channel 2 count = 8
	lda_24 xwa, 0x120000
	ldc_cr32 xwa, 0x00	; DMA channel 0 source = 0x120000
	ldb a, 0x0	; TMP94C241 encoding (21 00)
	ldc_cr8 a, 0x42	; DMA channel 0 mode = 0

	; Clear variables
	stdi8 1302, 0
	stdi8 1304, 0
	ret

; ==============================================================================
; INTER-CPU DMA TRANSFER ROUTINES (0xFF8604-0xFF881E) - 539 bytes
; ==============================================================================
;
; These routines implement the sub CPU's side of the 192KB payload loading
; protocol. The main CPU sends firmware payload data to the sub CPU via DMA
; through the inter-CPU latch at 0x120000.
;
; PAYLOAD LOADING PROTOCOL:
; -------------------------
; 1. Main CPU sends command byte with count via latch
; 2. Sub CPU receives interrupt, sets up DMA to receive data
; 3. Data is DMA'd from latch to sub CPU RAM
; 4. Sub CPU acknowledges via INTERCPU_STATUS handshake flags
; 5. Repeat until all 192KB is transferred
; 6. Main CPU sends E3 command to signal payload complete
; 7. Sub CPU jumps to payload entry point at 0x0400
;
; COMMAND TYPES:
; --------------
; E1: Two-phase transfer setup (6 bytes: dest_addr[4] + count[2])
; E2: Parameter block transfer (10 bytes: src[4] + dest[4] + count[2])
; E3: Payload complete signal (no data, just sets ready flag)
; 00-1F: Variable-length data (low 5 bits = count-1, high 3 bits = handler)
;
; DMA STATE MACHINE (DMA_XFER_STATE):
; -----------------------------------
; 0 = Idle (no transfer in progress)
; 1 = Single transfer pending (waiting for completion)
; 2 = Two-phase transfer (E1 mode: phase 1 done, phase 2 pending)
;
; ROUTINES:
; ---------
; SendData_Chunked  (0xFF8604): Break large transfers into 32-byte chunks
; SendData_Block    (0xFF8649): Send single data block with handshaking
; SendCmd_E3        (0xFF86AC): Signal payload ready to main CPU
; SendParams_E2     (0xFF86DC): Wait for DMA, then send E2 parameters
; TwoPhase_Transfer (0xFF874C): Execute E1 two-phase DMA sequence
; ==============================================================================

; ------------------------------------------------------------------------------
; SendData_Chunked (0xFF8604) - Send large data buffer in 32-byte chunks
; ------------------------------------------------------------------------------
; Breaks a large transfer into manageable 32-byte chunks to avoid overwhelming
; the inter-CPU communication channel. Used for bulk payload transfers.
;
; Input:  A   = command/channel byte
;         BC  = total byte count
;         XDE = source address in sub CPU memory
; Output: None (data sent via DMA)
; Modifies: IZ used as remaining count, stack frame for parameters
; ------------------------------------------------------------------------------
SendData_Chunked:
	dec 6, xsp	; Allocate 6 bytes on stack
	pushw iz	; Save IZ
	mrdd3 0xBF, 0x02, 0x62	; Save source address at (SP+2)
	ld iz, bc	; IZ = total byte count
	mrdd3 0xBF, 0x06, 0x41	; Save channel/command at (SP+6)
	cp iz, 0x20	; Is count <= 32?
	jr ule, SendData_Chunked__send_final	; Yes - send final chunk directly
SendData_Chunked__chunk_loop:
	mrdb3 0x8F, 0x06, 0x21	; A = channel/command
	extpfx2 0xD8, 0x12	; Zero-extend A to WA
	ldw bc, 0x20	; BC = 32 (chunk size)
	mrdl3 0xAF, 0x02, 0x22	; XDE = current source address
	calr SendData_Block	; Send 32-byte chunk
	ld xwa, 0x20	; XWA = 32
	mrdl3 0xAF, 0x02, 0x88	; Advance source address by 32
	sub iz, 0x20	; Subtract 32 from remaining count
	cp iz, 0x20	; Is remaining > 32?
	jr ugt, SendData_Chunked__chunk_loop	; Yes - continue chunking
SendData_Chunked__send_final:
	mrdb3 0x8F, 0x06, 0x21	; A = channel/command
	extpfx2 0xD8, 0x12	; Zero-extend A to WA
	ldto_berp C, 0xF8	; C = remaining count (low byte)
	extpfx2 0xD9, 0x12	; Zero-extend C to BC
	mrdl3 0xAF, 0x02, 0x22	; XDE = current source address
	calr SendData_Block	; Send final chunk
	popw iz	; Restore IZ
	inc 6, xsp	; Deallocate 6 bytes from stack
	ret

; ------------------------------------------------------------------------------
; SendData_Block (0xFF8649) - Send single data block with handshaking
; ------------------------------------------------------------------------------
; Core DMA send routine. Implements the full handshaking protocol:
; 1. Wait for main CPU ready (bit 4 of INTERCPU_STATUS)
; 2. Clear our ready flag, set DMA_XFER_STATE = 1
; 3. Send command byte: (channel << 5) | (count - 1)
; 4. Wait for main CPU acknowledgment
; 5. Set up DMA source/count, trigger transfer
; 6. Wait for DMA_XFER_STATE to return to 0
;
; Input:  A   = command/channel byte (used in high 3 bits)
;         BC  = byte count (1-32 bytes)
;         XDE = source address
; Output: None
; Timeout: 60000 iterations (~0.3 sec at 20MHz) before giving up
; ------------------------------------------------------------------------------
SendData_Block:
	cps c, 0	; Is count zero?
	ret z	; Yes - nothing to send
	lds ix, 0	; IX = timeout counter
SendData_Block__wait_ready1:
	bit_dd8 4, 0x34	; Check if other CPU ready
	jr z, SendData_Block__timeout1	; Not ready - check timeout
	res_dd8 0, 0x34	; Clear our ready flag
	stdi8 1302, 1	; Set DMA sync flag
	ld l, c	; L = byte count
	dec 1, l	; L = count - 1
	sll a, 5	; A = command << 5
	or a, l	; A = (command << 5) | (count - 1)
	st8_24 0x120000, a                    ; Send command+count to main CPU
	lds ix, 0	; Reset timeout counter
SendData_Block__wait_ready2:
	bit_dd8 4, 0x34	; Check if main CPU acknowledged
	jr nz, SendData_Block__timeout2	; Main CPU responded - check timeout
	set_dd8 0, 0x34	; Set our ready flag
	ldc_cr32 xde, 0x08	; DMA source = XDE
	extpfx2 0xD9, 0x12	; Zero-extend BC (count)
	ldc_cr16 bc, 0x48	; DMA count = BC
	stdi8 258, 22	; Set DMA mode
	set_dd8 2, 0x80	; Start DMA transfer
	cpdi8 1302, 0	; Is DMA complete?
	ret z	; Yes - return
SendData_Block__wait_dma_done:
	cpdi8 1302, 0	; Check DMA sync flag
	jr nz, SendData_Block__wait_dma_done	; Wait until cleared
	ret
SendData_Block__timeout1:
	ld hl, ix	; HL = timeout counter
	inc 1, ix	; Increment counter
	cp hl, 0xEA60	; Timeout limit (60000 iterations)
	jr ule, SendData_Block__wait_ready1	; Keep waiting if not timed out
	ret	; Timeout - give up
SendData_Block__timeout2:
	ld wa, ix	; WA = timeout counter
	inc 1, ix	; Increment counter
	cp wa, 0xEA60	; Timeout limit
	jr ule, SendData_Block__wait_ready2	; Keep waiting if not timed out
	set_dd8 0, 0x34	; Set ready flag before returning
	ret

; ------------------------------------------------------------------------------
; SendCmd_E3 (0xFF86AC) - Signal payload transfer complete
; ------------------------------------------------------------------------------
; Sends the E3 command to main CPU indicating that the 192KB payload has been
; successfully received and the sub CPU is ready to execute it.
;
; After this command, the main CPU knows the sub CPU will jump to 0x0400.
;
; Protocol:
; 1. Wait for main CPU ready
; 2. Send 0xE3 to inter-CPU latch
; 3. Wait for acknowledgment
; 4. Set our ready flag
;
; Input:  None
; Output: None
; Timeout: 60000 iterations before giving up
; ------------------------------------------------------------------------------
SendCmd_E3:
	lds bc, 0	; BC = timeout counter
SendCmd_E3__wait_ready:
	bit_dd8 4, 0x34	; Check if main CPU ready
	jr z, SendCmd_E3__timeout1	; Not ready - check timeout
	res_dd8 0, 0x34	; Clear our ready flag
	sti8_24 0x120000, 0xe3                 ; Send E3 command to main CPU
SendCmd_E3__wait_ack:
	bit_dd8 4, 0x34	; Check for acknowledgment
	jr nz, SendCmd_E3__timeout2	; Got response - handle in timeout2
SendCmd_E3__set_flag_ret:	; Success path AND timeout2 target
	set_dd8 0, 0x34	; Set our ready flag
	ret	; Done
SendCmd_E3__timeout1:
	ld wa, bc	; WA = timeout counter
	inc 1, bc	; Increment counter
	cp wa, 0xEA60	; Timeout limit (60000)
	jr ule, SendCmd_E3__wait_ready	; Keep waiting if not timed out
	ret	; Timeout - give up
SendCmd_E3__timeout2:
	ld wa, bc	; WA = timeout counter
	inc 1, bc	; Increment counter
	cp wa, 0xEA60	; Timeout limit
	jr ugt, SendCmd_E3__set_flag_ret	; Timed out - set flag and return
	jr SendCmd_E3__wait_ack	; Not timed out - keep waiting

; ------------------------------------------------------------------------------
; SendParams_E2 (0xFF86DC) - Send E2 parameter block to main CPU
; ------------------------------------------------------------------------------
; Waits for any pending DMA to complete, then sends an E2 command with a
; 10-byte parameter block containing transfer parameters.
;
; E2 Parameter Block (DMA_SETUP_PARAMS, 10 bytes):
;   Offset 0-3: XWA value (source address or parameter 1)
;   Offset 4-7: XDE value (destination address or parameter 2)
;   Offset 8-9: BC value (count or parameter 3)
;
; Protocol:
; 1. Wait for DMA_XFER_STATE = 0
; 2. Send 0xE2 command
; 3. Wait for main CPU ready
; 4. Build parameter block at DMA_SETUP_PARAMS
; 5. DMA transfer 10 bytes to main CPU
; 6. Wait for completion
;
; Input:  XWA, XDE, BC = parameters to pack into block
; Output: Parameter block sent to main CPU
; ------------------------------------------------------------------------------
SendParams_E2:
	lds ix, 0	; IX = timeout counter
SendParams_E2__wait_sync_clear:
	cpdi8 1302, 0	; Is DMA sync flag clear?
	jr z, SendParams_E2__sync_cleared	; Yes - proceed
SendParams_E2__timeout_wait:
	ld hl, ix	; HL = timeout counter
	inc 1, ix	; Increment counter
	cp hl, 0xEA60	; Timeout limit (60000)
	ret ugt	; Timeout - give up and return
	cpdi8 1302, 0	; Check sync flag again
	jr nz, SendParams_E2__timeout_wait	; Still not clear - keep waiting
SendParams_E2__sync_cleared:
	res_dd8 0, 0x34	; Clear our ready flag
	stdi8 1302, 1	; Set DMA sync flag
	sti8_24 0x120000, 0xe2                 ; Send E2 command to main CPU
	lds ix, 0	; Reset timeout counter
SendParams_E2__wait_cpu_ready:
	bit_dd8 4, 0x34	; Check if main CPU ready
	jr nz, SendParams_E2__timeout2	; Not ready yet - check timeout
	set_dd8 0, 0x34	; Set our ready flag
	ldada xhl, 1282	; XHL = address of DMA parameter block
	ld (xhl), xwa	; Store XWA parameter
	ld (xhl + 4), xde	; Store XDE parameter
	ld (xhl + 8), bc	; Store BC parameter
	ldc_cr32 xhl, 0x08	; DMA source = XHL (param block addr)
	ldw wa, 0xA	; WA = 10 (DMA count)
	ldc_cr16 wa, 0x48	; DMA count = 10
	stdi8 258, 22	; Set DMA mode
	set_dd8 2, 0x80	; Start DMA transfer
	setda 7, 1278	; Set DMA ready flag
	cpdi8 1302, 0	; Is DMA complete?
	ret z	; Yes - return
SendParams_E2__wait_dma_done:
	cpdi8 1302, 0	; Check DMA sync flag
	jr nz, SendParams_E2__wait_dma_done	; Wait until cleared
	ret
SendParams_E2__timeout2:
	ld hl, ix	; HL = timeout counter
	inc 1, ix	; Increment counter
	cp hl, 0xEA60	; Timeout limit
	jr ule, SendParams_E2__wait_cpu_ready	; Keep waiting if not timed out
	set_dd8 0, 0x34	; Set ready flag before returning
	ret

; ------------------------------------------------------------------------------
; TwoPhase_Transfer (0xFF874C) - Execute E1 two-phase DMA sequence
; ------------------------------------------------------------------------------
; Implements the E1 command protocol for transferring data that requires
; setup parameters before the actual data. Used for complex transfers where
; the destination and count need to be communicated first.
;
; PHASE 1: Send 6-byte setup block
;   - Source: E1_XFER_PARAMS (0x050C)
;   - Contains: dest_addr[4] + count[2]
;   - DMA_XFER_STATE: 2 -> 1 on completion
;
; DELAY: 200 iteration pause (hardware settling time)
;
; PHASE 2: Send actual data
;   - Source: Address from E2_XFER_PARAMS (0x053E)
;   - Count: From E2_XFER_PARAMS + 4
;   - DMA_XFER_STATE: 1 -> 0 on completion
;
; Input:  XWA = source address for phase 2 data
;         XDE = destination address (stored to both buffers)
;         BC  = byte count (stored to both buffers)
; Output: Data transferred in two phases
; Timing: 200-cycle delays between phases for hardware sync
; ------------------------------------------------------------------------------
TwoPhase_Transfer:
	pushw iz	; Save IZ
	lds iz, 0	; IZ = timeout counter
TwoPhase_Transfer__wait_sync:
	cpdi8 1302, 0	; Is DMA sync clear?
	jr z, TwoPhase_Transfer__sync_cleared	; Yes - proceed
TwoPhase_Transfer__timeout_sync:
	ld hl, iz	; HL = timeout counter
	inc 1, iz	; Increment counter
	cp hl, 0xEA60	; Timeout limit (60000)
	jrl ugt, TwoPhase_Transfer__exit	; Timeout - exit
	cpdi8 1302, 0	; Check sync again
	jr nz, TwoPhase_Transfer__timeout_sync	; Still not clear - keep waiting
TwoPhase_Transfer__sync_cleared:
	lds iz, 0	; Reset timeout counter
TwoPhase_Transfer__wait_cpu_ready:
	bit_dd8 4, 0x34	; Check if CPU ready
	jrl z, TwoPhase_Transfer__timeout_ready1	; Not ready - timeout handler
	res_dd8 0, 0x34	; Clear our ready flag
	stdi8 1302, 2	; Set sync flag to E1 mode
	sti8_24 0x120000, 0xe1                 ; Send E1 command
	lds iz, 0	; Reset timeout counter
TwoPhase_Transfer__wait_ack:
	bit_dd8 4, 0x34	; Check for acknowledgment
	jrl nz, TwoPhase_Transfer__timeout_ack	; Not acknowledged - timeout handler
	set_dd8 0, 0x34	; Set our ready flag
	; Phase 1: Set up first DMA transfer
	ldada xhl, 1342	; XHL = 0x053E (second buffer)
	ld (xhl), xwa	; Store XWA to buffer
	ldada xwa, 1292	; XWA = 0x050C (first buffer)
	ld (xwa), xde	; Store XDE to first buffer
	ld (xhl + 4), bc	; Store BC to second buffer+4
	ld (xwa + 4), bc	; Store BC to first buffer+4
	ldc_cr32 xwa, 0x08	; DMA source = first buffer (0x050C)
	lds wa, 6	; WA = 6 (DMA count)
	ldc_cr16 wa, 0x48	; DMA count = 6
	stdi8 258, 22	; Set DMA mode
	set_dd8 2, 0x80	; Start DMA transfer
	; Wait for first transfer to complete (sync flag = 1)
	cpdi8 1302, 1	; Is sync flag = 1?
	jr z, TwoPhase_Transfer__phase1_done	; Yes - phase 1 complete
TwoPhase_Transfer__wait_phase1:
	cpdi8 1302, 1	; Check sync flag
	jr nz, TwoPhase_Transfer__wait_phase1	; Wait until = 1
TwoPhase_Transfer__phase1_done:
	; Delay loop (200 iterations)
	lds iz, 0	; IZ = delay counter
	cp iz, 0xC8	; Counter reached 200?
	jr nc, TwoPhase_Transfer__delay1_done	; Yes - done
TwoPhase_Transfer__delay1_loop:
	nop	; Small delay
	inc 1, iz	; Increment counter
	cp iz, 0xC8	; Check again
	jr c, TwoPhase_Transfer__delay1_loop	; Continue if < 200
TwoPhase_Transfer__delay1_done:
	; Phase 2: Set up second DMA transfer
	ldada xwa, 1342	; XWA = 0x053E (second buffer)
	ld xbc, (xwa)	; XBC = contents of second buffer
	ldc_cr32 xbc, 0x08	; DMA source = XBC
	ld wa, (xwa + 4)	; WA = count from buffer+4
	ldc_cr16 wa, 0x48	; DMA count = WA
	stdi8 258, 22	; Set DMA mode
	set_dd8 2, 0x80	; Start DMA transfer
	; Wait for second transfer to complete (sync flag = 0)
	cpdi8 1302, 0	; Is sync flag = 0?
	jr z, TwoPhase_Transfer__phase2_done	; Yes - phase 2 complete
TwoPhase_Transfer__wait_phase2:
	cpdi8 1302, 0	; Check sync flag
	jr nz, TwoPhase_Transfer__wait_phase2	; Wait until = 0
TwoPhase_Transfer__phase2_done:
	; Second delay loop (200 iterations)
	lds iz, 0	; IZ = delay counter
	cp iz, 0xC8	; Counter reached 200?
	jr nc, TwoPhase_Transfer__delay2_done	; Yes - skip to exit jump
TwoPhase_Transfer__delay2_loop:
	nop	; Small delay
	inc 1, iz	; Increment counter
	cp iz, 0xC8	; Check again
	jr c, TwoPhase_Transfer__delay2_loop	; Continue if < 200
TwoPhase_Transfer__delay2_done:
	jr TwoPhase_Transfer__exit	; Unconditional jump to exit
TwoPhase_Transfer__timeout_ready1:
	ld hl, iz	; HL = timeout counter
	inc 1, iz	; Increment counter
	cp hl, 0xEA60	; Timeout limit
	jrl ule, TwoPhase_Transfer__wait_cpu_ready	; Keep waiting if not timed out
	jr TwoPhase_Transfer__exit	; Timeout - exit
TwoPhase_Transfer__timeout_ack:
	ld hl, iz	; HL = timeout counter
	inc 1, iz	; Increment counter
	cp hl, 0xEA60	; Timeout limit
	jrl ule, TwoPhase_Transfer__wait_ack	; Keep waiting if not timed out
	set_dd8 0, 0x34	; Set ready flag before exit
TwoPhase_Transfer__exit:
	popw iz	; Restore IZ
	ret

; ==============================================================================
; InterCPU_RX_Handler (0xFF881F) - Inter-CPU Command Receive Interrupt
; ==============================================================================
;
; Called when data arrives from main CPU via inter-CPU latch at 0x120000.
; This is the primary entry point for all incoming payload data during boot.
;
; The handler reads the command byte, decodes it, and sets up DMA to receive
; the associated data payload into the appropriate buffer.
;
; COMMAND DECODING:
; -----------------
; E1: Two-phase transfer setup
;     - Receives 6 bytes to E1_XFER_PARAMS (dest_addr[4] + count[2])
;     - Sets CMD_PROCESSING_STATE = 2 for phase 2 execution
;
; E2: Parameter block for bulk transfer
;     - Receives 10 bytes to CMD_E2_BUFFER (src[4] + dest[4] + count[2])
;     - Used for large payload chunks
;
; E3: Payload complete signal
;     - No data, just sets bit 6 of SUBCPU_STATUS_FLAGS
;     - Sub CPU can now jump to payload at 0x0400
;
; 00-1F: Variable-length data packets
;     - Low 5 bits = byte count - 1 (so 0x00 = 1 byte, 0x1F = 32 bytes)
;     - High 3 bits = handler index (looked up in table at 0x8000)
;     - Data received to CMD_DATA_BUFFER for handler processing
; ==============================================================================

	.org 0xFF881F - 0xFE0000, 0xFF

InterCPU_RX_Handler:
	push xwa
	bit_dd8 2, 0x34	; Check serial status
	jr nz, InterCPU_RX_Handler__exit
	ld8_24 a, 0x120000                    ; Read command from main CPU
	stda8 1306, a	; Save received byte
	cp a, 0xE1	; Command E1?
	jr nz, InterCPU_RX_Handler__not_e1
	; E1: Set up DMA for 6 bytes
	stdi8 1304, 2
	ldada xwa, 1348
	stda32 1298, xwa
	ldc_cr32 xwa, 0x20	; DMA channel 0 destination
	lds wa, 6
	ldc_cr16 wa, 0x40	; DMA channel 0 count = 6
	jr InterCPU_RX_Handler__start_dma
InterCPU_RX_Handler__not_e1:
	cp a, 0xE2	; Command E2?
	jr nz, InterCPU_RX_Handler__not_e2
	; E2: Set up DMA for 10 bytes
	stdi8 1304, 3
	ldada xwa, 1354
	stda32 1298, xwa
	ldc_cr32 xwa, 0x20	; DMA channel 0 destination
	ldw wa, 0xA
	ldc_cr16 wa, 0x40	; DMA channel 0 count = 10
	jr InterCPU_RX_Handler__start_dma
InterCPU_RX_Handler__not_e2:
	cp a, 0xE3	; Command E3?
	jr nz, InterCPU_RX_Handler__default_cmd
	; E3: Signal payload ready
	setda 6, 1278
	jr InterCPU_RX_Handler__clear_flag
InterCPU_RX_Handler__default_cmd:
	; Other commands: variable-length DMA based on low 5 bits
	stdi8 1304, 1
	ldada xwa, 1310
	stda32 1298, xwa
	ldc_cr32 xwa, 0x20	; DMA channel 0 destination
	ldda8 a, 1306
	and a, 0x1F	; Low 5 bits = count - 1
	inc 1, a
	extz wa
	ldc_cr16 wa, 0x40	; DMA channel 0 count
InterCPU_RX_Handler__start_dma:
	stdi8 256, 10	; Trigger DMA
InterCPU_RX_Handler__clear_flag:
	res_dd8 1, 0x34
InterCPU_RX_Handler__exit:
	pop xwa
	reti

; ==============================================================================
; DMA_Complete_Handler (0xFF889A) - DMA Transfer Complete Interrupt
; ==============================================================================
;
; Called when a DMA channel completes its transfer. Advances the DMA state
; machine to track multi-phase transfer progress:
;
;   State 2 (two-phase) -> State 1 (phase 1 done, phase 2 pending)
;   State 1 (single)    -> State 0 (idle, transfer complete)
;
; This handler is critical for the E1 two-phase transfer protocol, where
; phase 1 sends parameters and phase 2 sends the actual data.
; ==============================================================================

	.org 0xFF889A - 0xFE0000, 0xFF

DMA_Complete_Handler:
	res_dd8 2, 0x80	; Clear watchdog bit
	cpdi8 1302, 1	; State 1?
	jr nz, DMA_Complete_Handler__not_state1
	stdi8 1302, 0	; -> State 0
	jr DMA_Complete_Handler__done
DMA_Complete_Handler__not_state1:
	cpdi8 1302, 2	; State 2?
	jr nz, DMA_Complete_Handler__done
	stdi8 1302, 1	; -> State 1
DMA_Complete_Handler__done:
	reti

; ==============================================================================
; CMD_Dispatch_Handler (0xFF88B8) - Command Processing Dispatcher
; ==============================================================================
;
; Main processing handler that executes after DMA receives data. Dispatches
; based on CMD_PROCESSING_STATE to handle different phases of command processing.
;
; STATE MACHINE:
; --------------
; State 0: Idle - check watchdog only
; State 1: Data received - call handler from jump table based on command byte
; State 2: E1 phase 2 - set up secondary DMA from E1_XFER_PARAMS
; State 3: Completion - set status flags for main CPU acknowledgment
; State 4: Final - clear ready flag, return to idle
;
; The jump table at 0x8000 (DATA_TABLE_8000) contains handler addresses
; indexed by the high 3 bits of the command byte.
; ==============================================================================

	.org 0xFF88B8 - 0xFE0000, 0xFF

CMD_Dispatch_Handler:
	push xiz
	push xiy
	push xix
	push xhl
	push xde
	push xbc
	push xwa
	ldda8 a, 1304
	cps a, 4	; State 4?
	jr z, CMD_Dispatch_Handler__state4
	cps a, 3	; State 3?
	jr z, CMD_Dispatch_Handler__state3
	cps a, 2	; State 2?
	jr z, CMD_Dispatch_Handler__state2
	cps a, 1	; State 1?
	jr nz, CMD_Dispatch_Handler__check_watchdog
	; State 1: Process received data, call handler from table
	pushw 0x0
	pushw 0x51E
	ldda8 c, 1306
	ld a, c
	and a, 0x1F	; Low 5 bits = count
	inc 1, a
	extz wa
	pushw wa
	srl c, 5	; High 3 bits = handler index
	ld a, c
	extz wa
	sla wa, 2	; index * 4
	lda_24 xbc, 0xff8000                  ; Jump table at ROM start
	ld_sril3 XWA, 0x07, 0xE4, 0xE0	; Get handler address
	call (xwa)	; Call handler (if valid)
	inc 6, xsp	; Clean up stack
	stdi8 1304, 0
	jr CMD_Dispatch_Handler__set_flag_exit
CMD_Dispatch_Handler__state2:
	; State 2: Set up secondary DMA transfer
	ldada xwa, 1348
	ld xbc, (xwa)
	ldc_cr32 xbc, 0x20	; DMA channel 0 destination (from XBC)
	ld wa, (xwa + 4)
	ldc_cr16 wa, 0x40	; DMA channel 0 count
	stdi8 256, 10	; Trigger DMA
	stdi8 1304, 4	; -> State 4
	jr CMD_Dispatch_Handler__check_watchdog
CMD_Dispatch_Handler__state3:
	; State 3: Set completion flags
	stdi8 1308, 255
	stdi8 1304, 0
	set_dd8 1, 0x34
	setda 7, 1364
	jr CMD_Dispatch_Handler__check_watchdog
CMD_Dispatch_Handler__state4:
	; State 4: Final state, clear ready flag
	stdi8 1304, 0
	resda 7, 1278
CMD_Dispatch_Handler__set_flag_exit:
	set_dd8 1, 0x34
CMD_Dispatch_Handler__check_watchdog:
	bit_dd8 2, 0x80
	jr z, CMD_Dispatch_Handler__exit
	res_dd8 2, 0x80
	nop
	nop
	set_dd8 2, 0x80
CMD_Dispatch_Handler__exit:
	pop xwa
	pop xbc
	pop xde
	pop xhl
	pop xix
	pop xiy
	pop xiz
	reti
	ret	; 0xFF8955: Extra return instruction

; ==============================================================================
; INIT_MEMORY_TEST (0xFF8956) - Memory test/initialization
; ==============================================================================

	.org 0xFF8956 - 0xFE0000, 0xFF

INIT_MEMORY_TEST:
	stdi8 1366, 0
	set_dd8 1, 0x30
	bit_dd8 0, 0x30
	ret nz	; Return if bit set

	lds wa, 0
	calr MEM_TEST_ROUTINE	; 0xFF89FC (3-byte relative call)
	stda8 1366, l
	extz hl
	ld wa, hl
	calr ROM_CHECKSUM	; 0xFF8AB4 (3-byte relative call)
	stda8 1366, l
	calr HARDWARE_CALIBRATION_SEQUENCE	; 0xFF8C80 (3-byte relative call)
	cp hl, 0xFFFF
	jr nz, INIT_MEMORY_TEST__no_error
	setda 3, 1366
INIT_MEMORY_TEST__no_error:
	ldda8 a, 1366
	extz wa
	calr DELAY_ROUTINE	; 0xFF89A9 (3-byte relative call)

	; Clear serial buffer area
	sti16_24 0x110002, 0x0003              ; 7-byte encoding: f2 02 00 11 02 03 00
	ldada xbc, 1368
	ld xwa, xbc
	inc 8, xbc	; Increment XBC by 1
INIT_MEMORY_TEST__clear_loop:
	stib_dpi 0xE0, 0x00
	cp xwa, xbc
	jr c, INIT_MEMORY_TEST__clear_loop

INIT_MEMORY_TEST__serial_loop:
	calr SERIAL_INIT	; 0xFF8B07 (3-byte relative call)
	jr INIT_MEMORY_TEST__serial_loop	; Loop calling serial init forever

; ==============================================================================
; DELAY_ROUTINE (0xFF89A9) - Variable delay based on bit pattern in A
; Uses nested loops with timer register 0x30
; ==============================================================================

	.org 0xFF89A9 - 0xFE0000, 0xFF

DELAY_ROUTINE:
	ldb l, 0x0	; ld L, 00h (TMP94C241 encoding)
DELAY_ROUTINE__outer_loop:
	res_dd8 1, 0x30
	ldw bc, 0x4000	; Default count
	bit 0, a	; Check current bit
	jr z, DELAY_ROUTINE__skip_long
	ldw bc, 0xC000	; Longer delay if bit set
	jr DELAY_ROUTINE__delay_loop
DELAY_ROUTINE__skip_long:
	cps bc, 0
	jr z, DELAY_ROUTINE__next_bit
DELAY_ROUTINE__delay_loop:
	ldb e, 0x0	; ld E, 00h (TMP94C241 encoding)
DELAY_ROUTINE__inner_loop:
	inc 1, e
	cp e, 0x20
	jr c, DELAY_ROUTINE__inner_loop
	djnz xbc, DELAY_ROUTINE__delay_loop
DELAY_ROUTINE__next_bit:
	set_dd8 1, 0x30
	ldw bc, 0x4000
DELAY_ROUTINE__delay2_outer:
	ldb e, 0x0	; ld E, 00h (TMP94C241 encoding)
DELAY_ROUTINE__delay2_inner:
	inc 1, e
	cp e, 0x20
	jr c, DELAY_ROUTINE__delay2_inner
	djnz xbc, DELAY_ROUTINE__delay2_outer
	srl a, 1	; Next bit
	inc 1, l
	cps l, 3
	jr ule, DELAY_ROUTINE__outer_loop
	ret

; ==============================================================================
; LONG_DELAY (0xFF89E7) - Fixed long delay loop
; ==============================================================================

	.org 0xFF89E7 - 0xFE0000, 0xFF

LONG_DELAY:
	lds bc, 0
LONG_DELAY__outer:
	lds wa, 0
LONG_DELAY__inner:
	inc 1, wa
	cp wa, 0x100
	jr c, LONG_DELAY__inner
	inc 1, bc
	cp bc, 0x1000
	jr c, LONG_DELAY__outer
	ret

; ==============================================================================
; MEM_TEST_ROUTINE (0xFF89FC) - RAM Test
; Tests memory regions with patterns 0x5A5A5A5A and 0xA5A5A5A5
; Uses test configuration table at 0xFF8020
; Returns: L = error flags
; ==============================================================================

	.org 0xFF89FC - 0xFE0000, 0xFF

MEM_TEST_ROUTINE:
	lda xsp, (xsp - 12)	; Reserve 12 bytes on stack
	push xiz
	ld (xsp + 14), a	; Save error accumulator
	ld (xsp + 4), 0x0	; Test index = 0
MEM_TEST_ROUTINE__next_region:
	ld a, (xsp + 4)
	extz wa
	muls wa, 0xA	; Each entry is 10 bytes (TMP94C241 encoding)
	lda_24 xbc, 0xff8020                  ; Test config table
	st_dri3b B, 0x07, 0xE4, 0xE0	; Point to current entry
	ld xhl, (xde)	; Memory start address
	ld xiz, (xde + 4)	; Size in dwords
	srl xiz, 3	; Convert to iteration count
	or xiz, xiz
	jr z, MEM_TEST_ROUTINE__region_done
MEM_TEST_ROUTINE__test_loop:
	; Save original value
	ld xwa, (xhl)
	ld (xsp + 6), xwa
	; Write pattern 1: 0x5A5A5A5A
	ld xwa, 0x5A5A5A5A
	ld (xhl), xwa
	ld xiy, xhl
	lda xix, (xsp + 10)
	ldiw	; Copy to temp
	ldiw
	; Verify pattern 1
	lda xwa, (xsp + 10)
	ld xbc, xwa
	mriw4 0x90, 0x3F, 0x5A, 0x5A	; Check low word
	jr z, MEM_TEST_ROUTINE__low1_ok
	ld a, (xde + 8)	; Error code for low word
	or (xsp + 14), a
MEM_TEST_ROUTINE__low1_ok:
	mrdw5 0x99, 0x02, 0x3F, 0x5A, 0x5A	; Check high word at (XBC+2)
	jr z, MEM_TEST_ROUTINE__high1_ok
	ld a, (xde + 9)	; Error code for high word
	or (xsp + 14), a
MEM_TEST_ROUTINE__high1_ok:
	; Restore and test pattern 2
	ld xwa, (xsp + 6)
	st_dpil XWA, 0xEE	; Restore and advance
	ld xwa, (xhl)
	ld (xsp + 6), xwa
	; Write pattern 2: 0xA5A5A5A5
	ld xwa, 0xA5A5A5A5
	ld (xhl), xwa
	ld xiy, xhl
	lda xix, (xsp + 10)
	ldiw
	ldiw
	; Verify pattern 2
	lda xwa, (xsp + 10)
	ld xbc, xwa
	mriw4 0x90, 0x3F, 0xA5, 0xA5	; Check low word
	jr z, MEM_TEST_ROUTINE__low2_ok
	ld a, (xde + 8)
	or (xsp + 14), a
MEM_TEST_ROUTINE__low2_ok:
	mrdw5 0x99, 0x02, 0x3F, 0xA5, 0xA5	; Check high word at (XBC+2)
	jr z, MEM_TEST_ROUTINE__high2_ok
	ld a, (xde + 9)
	or (xsp + 14), a
MEM_TEST_ROUTINE__high2_ok:
	; Restore original
	ld xwa, (xsp + 6)
	st_dpil XWA, 0xEE
	sub xiz, 0x1
	jr nz, MEM_TEST_ROUTINE__test_loop
MEM_TEST_ROUTINE__region_done:
	incm8 1, (xsp + 4)
	cp (xsp + 4), 0x1	; Only 1 region in boot ROM
	jrl nz, MEM_TEST_ROUTINE__next_region	; Long relative jump needed (distance > 127)
	ld l, (xsp + 14)
	extz hl
	pop xiz
	lda xsp, (xsp + 12)
	ret

; ==============================================================================
; ROM_CHECKSUM (0xFF8AB4) - Calculate and verify boot ROM checksum
; Sums 0x800 words from 0xFE0000, compares against expected
; Returns: L = error flags (bit 2 set on mismatch)
; ==============================================================================

	.org 0xFF8AB4 - 0xFE0000, 0xFF

ROM_CHECKSUM:
	dec 4, xsp	; Reserve 4 bytes
	push xiz
	lda xix, (xsp + 4)
	mrid4 0xB4, 0x02, 0x00, 0x00	; Checksum accumulator 1 (TMP94C241 encoding)
	lda xhl, (xix + 2)
	mrid4 0xB3, 0x02, 0x00, 0x00	; Checksum accumulator 2 (TMP94C241 encoding)
	ldb w, 0x0	; Bank counter (TMP94C241 encoding)
ROM_CHECKSUM__bank_loop:
	ld xiy, 0xFE0000	; Boot ROM base
	lds32 xiz, 0	; Word counter
ROM_CHECKSUM__word_loop:
	ld c, w
	extz bc
	add bc, bc	; Bank offset
	st_dri3b B, 0x07, 0xF0, 0xE4
	ld bc, (xde)	; Get current sum
	ldfr_werp BC, 0xE2
	ld_spiw BC, 0xF5	; Read word from ROM
	add_werp BC, 0xE2	; Add to sum
	ld (xde), bc	; Store result
	inc 1, xiz
	cp xiz, 0x800
	jr c, ROM_CHECKSUM__word_loop
	inc 1, w
	cps w, 2
	jr c, ROM_CHECKSUM__bank_loop
	; Compare checksums
	ld bc, (xhl)
	cp bc, (xix)
	jr z, ROM_CHECKSUM__match
	set 2, a	; Mismatch error
ROM_CHECKSUM__match:
	ld l, a
	extz hl
	pop xiz
	inc 4, xsp
	ret

; ==============================================================================
; SERIAL_INIT (0xFF8B07) - Initialize serial communication
; Checks status bytes and sets interrupt flag accordingly
; ==============================================================================

	.org 0xFF8B07 - 0xFE0000, 0xFF

SERIAL_INIT:
	push_werp 0xFA
	ldi_berp 0xFB, 0	; Error accumulator
	calr CONTROL_PANEL_BIT_SET_CLEAR	; Initialize serial subsystem
	ldada xwa, 1368
	ld xbc, xwa
	lda xde, (xwa + 8)
SERIAL_INIT__check_loop:
	ldto_berp A, 0xFB
	or_spib_rm A, 0xE4	; OR all status bytes
	ldfr_berp A, 0xFB
	cp xbc, xde
	jr c, SERIAL_INIT__check_loop
	cpi_berp 0xFB, 0
	jr z, SERIAL_INIT__no_error
	res_dd8 1, 0x30	; Disable timer interrupt on error
	jr SERIAL_INIT__done
SERIAL_INIT__no_error:
	set_dd8 1, 0x30	; Enable timer interrupt
SERIAL_INIT__done:
	pop_werp 0xFA
	ret

; ==============================================================================
; CONTROL_PANEL_BIT_SET_CLEAR (0xFF8B37) - LED/Output bit manipulation routine
;
; This routine sets or clears bits in an output buffer based on input parameters.
; Parameters are passed on stack:
;   (SP+0): Button/LED index (0x24-based offset)
;   (SP+1): Action (0 = clear bit, non-zero = set bit)
;
; The routine calculates:
;   - Byte offset = (index - 0x24) >> 3 (which byte in buffer)
;   - Bit position = (index - 0x24) & 7 (which bit in byte)
;   - Buffer base = 0x0558
;
; Uses INTER_CPU_LATCH_READ_DISPATCH to send/receive data to hardware.
; ==============================================================================

	.org 0xFF8B37 - 0xFE0000, 0xFF

CONTROL_PANEL_BIT_SET_CLEAR:
	dec 2, xsp	; Reserve 2 bytes on stack for local vars
	lda xwa, (xsp)	; XWA = pointer to stack frame
	calr INTER_CPU_LATCH_READ_DISPATCH	; Call to get/send data
	cp hl, 0xFFFF	; Check return value
	jr z, CONTROL_PANEL_BIT_SET_CLEAR__done	; If -1 (error), skip to done

CONTROL_PANEL_BIT_SET_CLEAR__loop:
	lda xbc, (xsp)	; XBC = pointer to parameters
	ld e, (xbc)	; ld E, (XBC) - Load LED/button index
	sub e, 0x24	; E = index - 0x24 (normalize to 0-based)
	ld l, e	; L = normalized index
	srl l, 3	; L = index >> 3 (byte offset)
	and l, 0x7	; L = byte offset (mask to 0-7)
	and e, 0x7	; E = bit position (index & 7)
	ld a, e	; A = bit position
	ld e, l	; E = byte offset
	extz de	; Zero-extend DE (byte offset in DE)
	ldada xix, 1368	; XIX = buffer base address
	lds hl, 1	; HL = initial bit mask (1)
	and a, 0xF	; Mask bit position to 0-15
	jr z, CONTROL_PANEL_BIT_SET_CLEAR__skip_shift	; If A=0, skip shift (bit already = 1)
	slaa hl	; HL = HL << A (create bit mask)
CONTROL_PANEL_BIT_SET_CLEAR__skip_shift:
	extz xde	; Zero-extend XDE (32-bit offset)
	add xde, xix	; XDE = buffer base + byte offset
	cp (xbc + 1), 0x0	; Check action parameter
	jr z, CONTROL_PANEL_BIT_SET_CLEAR__clear_bit	; If 0, clear the bit
	or (xde), l	; Set bit: buffer[offset] |= mask
	jr CONTROL_PANEL_BIT_SET_CLEAR__next	; Jump to next iteration (always)
CONTROL_PANEL_BIT_SET_CLEAR__clear_bit:
	cpl hl	; Complement mask (for AND)
	and (xde), l	; Clear bit: buffer[offset] &= ~mask
CONTROL_PANEL_BIT_SET_CLEAR__next:
	ld xwa, xbc	; XWA = parameter pointer
	calr INTER_CPU_LATCH_READ_DISPATCH	; Call to send/get next item
	cp hl, 0xFFFF	; Check return value
	jr nz, CONTROL_PANEL_BIT_SET_CLEAR__loop	; If not -1, continue loop

CONTROL_PANEL_BIT_SET_CLEAR__done:
	inc 2, xsp	; Release 2 bytes from stack
	ret

; ==============================================================================
; INTER_CPU_LATCH_READ_DISPATCH (0xFF8B89) - Inter-CPU communication handler
;
; Reads data from inter-CPU communication latches at 0x110000-0x110002.
; Checks status bits and dispatches to NOTE_VELOCITY_LOOKUP_CALCULATE for processing.
;
; Input: XWA = pointer to parameter buffer
; Output: HL = 0 on success, 0xFFFF on error/no data
; ==============================================================================

	.org 0xFF8B89 - 0xFE0000, 0xFF

INTER_CPU_LATCH_READ_DISPATCH:
	push xiz
	ld xiz, xwa	; Save parameter pointer in XIZ
	ld16_24 xhl, 0x110002                 ; Read status register
	bit 0, hl	; Check bit 0 (data available?)
	jr z, INTER_CPU_LATCH_READ_DISPATCH__error	; If not set, return error

	ld16_24 xwa, 0x110000                 ; Read data word from latch
	ld b, a	; B = low byte
	and b, 0xFF	; Mask to byte
	srl wa, 8	; WA >>= 8 (get high byte in A)
	and a, 0xFF	; Mask to byte
	ld c, b	; C = copy of low byte
	ld e, a	; E = high byte
	cp a, 0xFF	; Check if high byte is 0xFF
	jr z, INTER_CPU_LATCH_READ_DISPATCH__check_bit7	; If so, check bit 7 path
	bit 1, hl	; Check bit 1 of status
	jr z, INTER_CPU_LATCH_READ_DISPATCH__process_normal	; If not set, process normally

INTER_CPU_LATCH_READ_DISPATCH__check_bit7:
	bit 7, b	; Check bit 7 of low byte
	jr nz, INTER_CPU_LATCH_READ_DISPATCH__error	; If set, return error
	ld xwa, xiz	; Restore parameter pointer
	calr NOTE_VELOCITY_LOOKUP_CALCULATE	; Call processing routine
	ld (xiz + 1), 0x0	; Clear byte at param+1
	jr INTER_CPU_LATCH_READ_DISPATCH__success	; Jump to success (always)

INTER_CPU_LATCH_READ_DISPATCH__process_normal:
	ld xwa, xiz	; Restore parameter pointer
	calr NOTE_VELOCITY_LOOKUP_CALCULATE	; Call processing routine

INTER_CPU_LATCH_READ_DISPATCH__success:
	lds hl, 0	; Return success
	jr INTER_CPU_LATCH_READ_DISPATCH__done	; Jump to done (always)

INTER_CPU_LATCH_READ_DISPATCH__error:
	ldw hl, 0xFFFF	; Return error (-1)

INTER_CPU_LATCH_READ_DISPATCH__done:
	pop xiz
	ret

; ==============================================================================
; NOTE_VELOCITY_LOOKUP_CALCULATE (0xFF8BD2) - Note/velocity calculation routine
;
; Calculates velocity values based on note index and lookup tables.
; Uses tables at 0xFF804C, 0xFF8040, 0xFF802A, 0xFF802C, 0xFF814C.
;
; Input: XWA = pointer to output buffer
;        C = note index (low byte from latch)
;        E = velocity index (high byte from latch)
; ==============================================================================

	.org 0xFF8BD2 - 0xFE0000, 0xFF

NOTE_VELOCITY_LOOKUP_CALCULATE:
	stdi8 1376, 6	; Set mode/flag byte
	ld l, c	; L = note index
	res 7, l	; Clear bit 7
	add l, 0x24	; Add 0x24 offset
	ld (xwa), l	; Store adjusted note to output[0]
	bit 7, c	; Check bit 7 of original C
	jrl z, NOTE_VELOCITY_LOOKUP_CALCULATE__zero_velocity	; If clear, set velocity to 0

	; Calculate velocity from tables
	ld c, e	; C = velocity index
	extz bc	; Zero-extend BC
	lda_24 xde, 0xff804c                  ; XDE = velocity curve table base
	lds32 xhl, 0	; Clear XHL
	ld_srib3 L, 0x07, 0xE8, 0xE4	; L = table[velocity_index]
	ld16_24 xbc, 0xff802a                 ; BC = parameter from table
	sub hl, bc	; HL = L - BC
	lda_24 xde, 0xff8040                  ; XDE = another table
	ld c, (xde)	; C = table[0]
	extz bc	; Zero-extend BC
	muls xbc, xhl	; XBC = BC * HL (signed)
	ld16_24 xhl, 0xff802c                 ; HL = divisor from table
	exts xbc	; Sign-extend XBC
	divs xbc, xhl	; XBC = XBC / HL (signed)
	ld hl, bc	; HL = quotient
	ld c, (xde + 1)	; C = table[1] (offset)
	extz bc	; Zero-extend BC
	add bc, hl	; BC = BC + HL
	ld hl, bc	; HL = result
	exts xhl	; Sign-extend XHL

	; Get note and check for special semitones
	ld c, (xwa)	; C = adjusted note
	extz bc	; Zero-extend BC
	div c, 0xC	; C = note / 12, B = note % 12 (semitone)
	ld c, b	; C = semitone (0-11)
	cp c, 0xA	; Is it A# (10)?
	jr z, NOTE_VELOCITY_LOOKUP_CALCULATE__apply_offset
	cp c, 0x8	; Is it G# (8)?
	jr z, NOTE_VELOCITY_LOOKUP_CALCULATE__apply_offset
	cps c, 6	; Is it F# (6)?
	jr z, NOTE_VELOCITY_LOOKUP_CALCULATE__apply_offset
	cps c, 3	; Is it D# (3)?
	jr z, NOTE_VELOCITY_LOOKUP_CALCULATE__apply_offset
	cps c, 1	; Is it C# (1)?
	jr nz, NOTE_VELOCITY_LOOKUP_CALCULATE__clamp_velocity	; If not a sharp, skip offset

NOTE_VELOCITY_LOOKUP_CALCULATE__apply_offset:
	lds32 xbc, 0	; Clear XBC
	ld c, (xde + 2)	; C = offset for sharp notes
	sub xhl, xbc	; XHL = XHL - offset

NOTE_VELOCITY_LOOKUP_CALCULATE__clamp_velocity:
	; Clamp velocity to 0-255 range
	ld xde, 0xFF	; Max velocity = 255
	cp xhl, 0xFF	; Compare with max
	jr gt, NOTE_VELOCITY_LOOKUP_CALCULATE__use_max	; If greater, use max
	ld xde, xhl	; Otherwise use calculated value
NOTE_VELOCITY_LOOKUP_CALCULATE__use_max:
	lds32 xbc, 0	; Min velocity = 0
	cp xde, 0x0	; Compare with min
	jr lt, NOTE_VELOCITY_LOOKUP_CALCULATE__use_min	; If less, use min
	ld xbc, xde	; Otherwise use clamped value
NOTE_VELOCITY_LOOKUP_CALCULATE__use_min:
	; Look up final velocity in curve table
	extz bc	; Zero-extend BC (velocity 0-255)
	lda_24 xde, 0xff814c                  ; XDE = final velocity curve table
	ld_srib3 C, 0x07, 0xE8, 0xE4	; C = curve[velocity]
	ld (xwa + 1), c	; Store final velocity to output[1]
	ret

NOTE_VELOCITY_LOOKUP_CALCULATE__zero_velocity:
	ld (xwa + 1), 0x0	; Store 0 velocity to output[1]
	ret

; ==============================================================================
; AUDIO_HW_WRITE_READ (0xFF8C75) - Hardware register write helper
;
; Writes WA to address 0x100000, reads HL from 0x100004.
; ==============================================================================

	.org 0xFF8C75 - 0xFE0000, 0xFF

AUDIO_HW_WRITE_READ:
	st16_24 0x100000, xwa                 ; Write WA to hardware register
	ld16_24 xhl, 0x100004                 ; Read status/result
	ret

; ==============================================================================
; HARDWARE_CALIBRATION_SEQUENCE (0xFF8C80) - Hardware communication/calibration routine
;
; Complex routine that communicates with hardware at 0x100000.
; Performs some kind of calibration or initialization sequence.
; Loops up to 1000 times (0x3E8) checking for hardware response.
; Returns IZ value (0 on success, 0xFFFF on timeout/error).
; ==============================================================================

	.org 0xFF8C80 - 0xFE0000, 0xFF

HARDWARE_CALIBRATION_SEQUENCE:
	push xiz
	ldw iz, 0xFFFF	; Initialize error flag to -1

	; First hardware write sequence
	sti16_24 0x100000, 0x0840              ; Write 0x0840 to hardware reg
	nop
	sti16_24 0x100002, 0xff00              ; Write 0xFF00 to hardware reg+2
	jr __jrt_nop_FF8C95	; Short delay (jump to next instruction)
__jrt_nop_FF8C95:
	nop
	nop
	nop

	; Second hardware write sequence
	sti16_24 0x100000, 0x0800              ; Write 0x0800 to hardware reg
	nop
	sti16_24 0x100002, 0xff80              ; Write 0xFF80 to hardware reg+2
	jr __jrt_nop_FF8CA9	; Short delay
__jrt_nop_FF8CA9:
	nop
	nop
	nop

	; Call HARDWARE_PARAM_BLOCK_WRITE with parameter block at 0xFF824C
	lds wa, 0
	ld xbc, 0xFF824C	; Parameter block address
	calr HARDWARE_PARAM_BLOCK_WRITE	; Write parameters to hardware

	; Read back and verify
	ld16_24 xbc, 0xff824c                 ; Read first word from param block
	lds wa, 0
	calr HARDWARE_VERIFY_WRITE	; Call verification routine

	; Check timeout counter
	cp_erpw 0xFA, 0xE8, 0x03	; Compare with 1000
	jr nc, HARDWARE_CALIBRATION_SEQUENCE__exit	; If >= 1000, exit (timeout)

HARDWARE_CALIBRATION_SEQUENCE__retry_loop:
	lds wa, 0
	calr AUDIO_HW_WRITE_READ	; Read hardware status
	cps hl, 0	; Check result
	jr z, HARDWARE_CALIBRATION_SEQUENCE__success	; If 0, hardware responded

	; Hardware still busy, reset and retry
	lds iz, 0	; Clear error flag (will succeed)

	; Repeat first hardware write sequence
	sti16_24 0x100000, 0x0840
	nop
	sti16_24 0x100002, 0xff00
	jr __jrt_nop_FF8CE3
__jrt_nop_FF8CE3:
	nop
	nop
	nop

	; Repeat second hardware write sequence
	sti16_24 0x100000, 0x0800
	nop
	sti16_24 0x100002, 0xff80
	jr __jrt_nop_FF8CF7
__jrt_nop_FF8CF7:
	nop
	nop
	nop
	jr HARDWARE_CALIBRATION_SEQUENCE__exit	; Exit after reset sequence

HARDWARE_CALIBRATION_SEQUENCE__success:
	inc1_werp 0xFA	; Increment retry counter
	cp_erpw 0xFA, 0xE8, 0x03	; Compare with 1000
	jr c, HARDWARE_CALIBRATION_SEQUENCE__retry_loop	; If < 1000, continue loop

HARDWARE_CALIBRATION_SEQUENCE__exit:
	ld hl, iz	; Return IZ as result
	pop xiz
	ret

