	st16_24 0x100000, xwa                 ; Address = base + 0x40
	nop
	ld xbc, (xsp + 2)	; Restore XBC
	ld wa, (xbc + 2)	; Get param[2:3]
	st16_24 0x100002, xwa                 ; Write data
